List<Pair<List<Pair<Integer,Integer>>,E>> computeGlobalSeparatorList(Graph<E> graph) {
    List<Pair<List<Pair<Integer,Integer>>,E>> globalSeparatorList = new ArrayList<>();

    // Iterate over all edges in the graph
    for (E edge : graph.getEdges()) {
        // Get the neighbors of the edge
        List<Vertex> neighbors = graph.getNeighbors(edge);

        // Initialize a list to store the minimal separators for the current edge
        List<Pair<Integer,Integer>> minimalSeparators = new ArrayList<>();

        // Iterate over all pairs of neighbors to find minimal separators
        for (int i = 0; i < neighbors.size(); i++) {
            for (int j = i + 1; j < neighbors.size(); j++) {
                List<Vertex> commonNeighbors = new ArrayList<>(neighbors.get(i).getNeighbors());
                commonNeighbors.retainAll(neighbors.get(j).getNeighbors());
                commonNeighbors.remove(neighbors.get(i)); // Remove the vertex itself
                commonNeighbors.remove(neighbors.get(j)); // Remove the neighboring vertex

                if (!commonNeighbors.isEmpty()) {
                    // Sort the common neighbors by their indices
                    commonNeighbors.sort(Comparator.comparingInt(Vertex::getIndex));

                    // Add the minimal separator as a pair of indices
                   minimalSeparators.add(Pair.with(commonNeighbors.get(0).getIndex(), commonNeighbors.get(commonNeighbors.size() - 1).getIndex()));
                }
            }
        }

        // Add the list of minimal separators for the current edge to the global separator list
        globalSeparatorList.add(Pair.with(minimalSeparators, edge));
    }

    return globalSeparatorList;
}

