    int index = i;
    while (bb.hasRemaining()) {
        byte b = bb.get();
        if (b >= 0) {
            sb.append((char) b);
            index++;
        } else {
            int leadingOnes = 0;
            int val = (int) b & 0xFF;
            do {
                val <<= 1;
                leadingOnes++;
            } while ((val & 0x80) != 0);

            if (leadingOnes == 1 || leadingOnes > 4) {
                sb.append('?'); // Invalid octet sequence, replace with '?' character
                index++;
            } else {
                int numOfAdditionalBytes = leadingOnes - 1;
                if (bb.remaining() < numOfAdditionalBytes) {
                    sb.append('?'); // Not enough bytes for the sequence, replace with '?'
                    index++;
                } else {
                    int codePoint = 0;
                    for (int j = 0; j < numOfAdditionalBytes; j++) {
                        b = bb.get();
                        codePoint = (codePoint << 6) | (b & 0x3F);
                    }
                    sb.appendCodePoint(codePoint);
                    index += 1 + numOfAdditionalBytes;
                }
            }
        }
    }
    return index;
}

