public void readFrom(final InputStream in) throws IOException {
    // Clear the existing buffer
    this.buffer.clear();

    // Reset the read pointer to the start of the buffer
    this.readPointer = 0;

    // Fill the buffer with the data from the input stream
    int bytesRead = in.read(this.buffer.array(), this.readPointer, this.buffer.capacity() - this.readPointer);

    // If the end of the stream is reached, throw an exception
    if (bytesRead == -1) {
        throw new IOException("Unexpected end of stream");
    }

    // Update the read pointer
    this.readPointer += bytesRead;
}

