private void pop(final String descriptor) {
    int count = 0;
    int i = 0;
    while (i < descriptor.length()) {
        char c = descriptor.charAt(i);
        if (c == 'L') {
            // Pop until ';' is found
            while (i < descriptor.length() && descriptor.charAt(i) != ';') {
                i++;
            }
            i++; // Skip ';'
            count++;
        } else if (c == ')') {
            // Method descriptor, pop arguments
            break;
        } else {
            // Single type, pop one
            count++;
            i++;
        }
    }
    // Pop the specified count from the output frame stack
    outputFrameStack.pop(count);
}

